-- Login (server-level)
CREATE LOGIN peter WITH PASSWORD = 'StrongP@ss123';

-- User (database-level)
CREATE USER peter FOR LOGIN peter;

-- Grant read access
GRANT SELECT ON People TO peter;

-- Deny writes explicitly
DENY INSERT, UPDATE, DELETE ON People TO peter;

-- Create a role
CREATE ROLE SalesAppWriter;

-- Grant it the permissions it needs
GRANT INSERT, UPDATE, DELETE ON Sales.Orders TO SalesAppWriter;
GRANT SELECT ON Sales.OrderItems TO SalesAppWriter;

-- Add users to the role
ALTER ROLE SalesAppWriter ADD MEMBER peter;
